651	// loadLocked reads and validates the committed file. Caller must hold the
652	// exclusive flock; the in-process mutex is taken by the public Open path.
653	func (s *Store) loadLocked() error {
654		raw, err := os.ReadFile(s.dataPath())
655		if errors.Is(err, os.ErrNotExist) {
656			s.data = envelope{Format: FormatVersion}
657			return nil
658		}
659		if err != nil {
660			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
661		}
662		if len(strings.TrimSpace(string(raw))) == 0 {
663			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
664		}
665	
666		var env envelope
667		if err := json.Unmarshal(raw, &env); err != nil {
668			// Shape failures surfaced by the persisted-definition decoders are
669			// integrity failures, not JSON syntax errors; report their detail
670			// instead of the generic "not valid JSON" wording.
671			var se StoreError
672			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
673				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
674			}
675			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
676		}
677		if env.Format == 0 {
678			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
679		}
680		if env.Format != FormatVersion {
681			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
682				s.dataPath(), env.Format, FormatVersion)
683		}
684		if err := validateEnvelope(env); err != nil {
685			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
686		}
687		s.data = env
688		return nil
689	}
690	
691	// commitLocked writes the pending state atomically: temp file → fsync →
692	// rename → fsync directory. Caller must hold both the in-process mutex and
693	// the exclusive flock; all in-memory mutations must already have happened and
694	// been rule-checked, so a failure here occurs before any success is reported.
695	func (s *Store) commitLocked() error {
696		s.data.Format = FormatVersion
697		// Stable output: records are stored sorted so files are deterministic.
698		sortEnvelope(&s.data)
699	
700		payload, err := json.MarshalIndent(&s.data, "", "  ")
701		if err != nil {
702			return fmt.Errorf("cannot encode data: %w", err)
703		}
704		payload = append(payload, '\n')
705	
706		tmp := s.tmpPath()
707		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
708		if err != nil {
709			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
710		}
711		if _, err := f.Write(payload); err != nil {
712			f.Close()
713			os.Remove(tmp)
714			return fmt.Errorf("cannot write staged data: %w", err)
715		}
716		if err := f.Sync(); err != nil {
717			f.Close()
718			os.Remove(tmp)
719			return fmt.Errorf("cannot flush staged data: %w", err)
720		}
721		if err := f.Close(); err != nil {
722			os.Remove(tmp)
723			return fmt.Errorf("cannot finish staged data: %w", err)
724		}
725		if err := os.Rename(tmp, s.dataPath()); err != nil {
726			os.Remove(tmp)
727			return fmt.Errorf("cannot commit data file: %w", err)
728		}
729		if err := syncDir(s.dir); err != nil {
730			// The rename already happened; lack of dir fsync only weakens crash
731			// durability, never correctness of what is visible now.
732			return nil
733		}
734		return nil
735	}
736	
737	// withLock runs fn under the in-process mutex and an exclusive flock, then
738	// atomically commits when fn requests it. The on-disk state is re-read after
739	// acquiring the lock, so concurrent commits from another process or another
740	// handle are always observed. Operations validate before mutating; a rejected
741	// operation (commit=false or an error) writes nothing and leaves committed
742	// state unchanged.
743	func (s *Store) withLock(fn func() (commit bool, err error)) error {
744		s.mu.Lock()
745		defer s.mu.Unlock()
746		if s.lock == nil {
747			return invalidf("store is closed")
748		}
749		if err := lockExclusive(s.lock); err != nil {
750			return fmt.Errorf("cannot lock data directory: %w", err)
751		}
752		defer unlockLock(s.lock)
753	
754		if err := s.loadLocked(); err != nil {
755			return err
756		}
757		commit, err := fn()
758		if err != nil {
759			return err
760		}
761		if !commit {
762			return nil
763		}
764		return s.commitLocked()
765	}
766	
767	// withLockRead runs fn under a shared flock over freshly reloaded state.
768	func (s *Store) withLockRead(fn func() error) error {
769		s.mu.Lock()
770		defer s.mu.Unlock()
771		if s.lock == nil {
772			return invalidf("store is closed")
773		}
774		if err := lockShared(s.lock); err != nil {
775			return fmt.Errorf("cannot lock data directory: %w", err)
776		}
777		defer unlockLock(s.lock)
778		if err := s.loadLocked(); err != nil {
779			return err
780		}
781		return fn()
782	}
783	
784	func sortEnvelope(env *envelope) {
785		sort.Slice(env.Circuits, func(i, j int) bool {
786			if env.Circuits[i].Name != env.Circuits[j].Name {
787				return env.Circuits[i].Name < env.Circuits[j].Name
788			}
789			return env.Circuits[i].Version < env.Circuits[j].Version
790		})
791		sort.Slice(env.Setups, func(i, j int) bool {
792			if env.Setups[i].Name != env.Setups[j].Name {
793				return env.Setups[i].Name < env.Setups[j].Name
794			}
795			return env.Setups[i].Version < env.Setups[j].Version
796		})
797		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
798		sort.Slice(env.Artifacts, func(i, j int) bool {
799			if env.Artifacts[i].Name != env.Artifacts[j].Name {
800				return env.Artifacts[i].Name < env.Artifacts[j].Name
801			}
802			return env.Artifacts[i].Version < env.Artifacts[j].Version
803		})
804	}
805	
806	// validateEnvelope re-checks every invariant on load so a tampered or
807	// hand-edited file cannot bypass the domain rules.
808	//
809	// A stored constraint definition is parsed and canonicalized exactly once
810	// per load: the circuit pass validates every defined version against its
811	// declared counts and keeps the resulting canonical form, and the artifact
812	// pass reuses that same form to verify the recorded modulus, constraint
813	// count and hash. The map is built fresh on each call, so the reuse never
814	// carries a judgment across loads — every read validates the bytes found on
815	// disk at that moment.
816	func validateEnvelope(env envelope) error {
817		seenCircuit := make(map[[2]string]bool)
818		circuitOK := make(map[[2]string]bool)
819		canonicalDefs := make(map[[2]string]*canonicalDefinition)
820		for i, c := range env.Circuits {
821			key := [2]string{c.Name, itoa(c.Version)}
822			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
823				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
824			}
825			if c.Version <= 0 {
826				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
827			}
828			if seenCircuit[key] {
829				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
830			}
831			seenCircuit[key] = true
832			if c.Constraints <= 0 {
833				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
834			}
835			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
836				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
837			}
838			// The same representability rule the write path enforces: wire 0 plus
839			// every declared input must fit inside the platform's int. A record
840			// beyond that bound can never have been written by this build and
841			// cannot be checked safely, so the directory is corrupt rather than
842			// silently narrowed or read with a wrapped-around layout.
843			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
844				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
845					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
846			}
847			if c.Definition != nil {
848				def, err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition)
849				if err != nil {
850					return err
851				}
852				canonicalDefs[key] = def
853			}
854			circuitOK[key] = true
855		}
856		seenSetup := make(map[[2]string]bool)
857		for i, p := range env.Setups {
858			key := [2]string{p.Name, itoa(p.Version)}
859			if !circuitOK[key] {
860				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
861			}
862			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
863			if c == nil || !c.Frozen {
864				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
865			}
866			if seenSetup[key] {
867				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
868			}
869			seenSetup[key] = true
870		}
871		seenJob := make(map[string]bool)
872		for i, j := range env.Jobs {
873			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
874				return fmt.Errorf("job #%d has an empty or blank id", i+1)
875			}
876			if seenJob[j.ID] {
877				return fmt.Errorf("job %q appears more than once", j.ID)
878			}
879			seenJob[j.ID] = true
880			if j.Kind != "prove" {
881				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
882			}
883			if j.Attempt <= 0 {
884				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
885			}
886			key := [2]string{j.Circuit, itoa(j.Version)}
887			if !circuitOK[key] {
888				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
889			}
890			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
891			if c == nil || !c.Frozen {
892				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
893			}
894			if !seenSetup[key] {
895				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
896			}
897			// A recorded compiled-artifact binding must still resolve against the
898			// pinned version's artifact; a dangling or mismatched binding makes
899			// the file unreadable rather than silently dropping the binding.
900			if j.CompiledHash != "" {
901				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
902				if artifact == nil {
903					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
904				}
905				if artifact.Hash != j.CompiledHash {
906					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
907						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
908				}
909			}
910		}
911		seenArtifact := make(map[[2]string]bool)
912		for i, a := range env.Artifacts {
913			key := [2]string{a.Name, itoa(a.Version)}
914			if !circuitOK[key] {
915				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
916			}
917			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
918			if c == nil || !c.Frozen {
919				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
920			}
921			if seenArtifact[key] {
922				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
923			}
924			seenArtifact[key] = true
925			if c.Definition == nil {
926				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
927			}
928			if a.Constraints != c.Constraints {
929				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
930					a.Name, a.Version, a.Constraints, c.Constraints)
931			}
932			// The circuit pass above already validated and canonicalized this
933			// version's definition (every artifact requires a defined version,
934			// checked just above), so the artifact check reuses that one result
935			// instead of re-parsing and re-normalizing the same stored definition.
936			def := canonicalDefs[key]
937			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
938				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
939			}
940			wantHash := artifactHash(a.Name, a.Version, def)
941			if a.Hash != wantHash {
942				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
943					a.Name, a.Version, a.Hash, wantHash)
944			}
945		}
946		return nil
947	}
948	
949	// validatePersistDefinition re-validates a stored definition against its
950	// version's declared counts: prime modulus, in-range wires and an exact
951	// constraint count match. On success it returns the canonical form built
952	// during validation, so a later check against the same version's artifact
953	// reuses it instead of parsing and normalizing the definition a second time.
954	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) (*canonicalDefinition, error) {
955		parsed, err := definitionFromPersist(*def, public, private)
956		if err != nil {
957			return nil, fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
958		}
959		if !parsed.compatibleWith(constraints, public, private) {
960			return nil, fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
961		}
962		return parsed, nil
963	}
964	
965	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
966		for i := range cs {
967			if cs[i].Name == name && cs[i].Version == version {
968				return &cs[i]
969			}
970		}
971		return nil
972	}
973	
974	func itoa(v int) string { return fmt.Sprintf("%d", v) }
975

